 const search = document.createElement('input'); search.type='search'; search.placeholder='Buscar emojis…'; search.setAttribute('aria-label','Buscar emojis en todas las categorías'); search.style.cssText='width:100%;box-sizing:border-box;padding:6px;margin:4px 0'; panel.append(search);
 const normalize = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const close = document.createElement('button'); close.type='button'; close.textContent='Cerrar'; panel.append(close);
 document.body.append(panel);
 for(const name of Object.keys(groups)) category.add(new Option(name,name));
