 addRotation('Girar 45° a la izquierda', -45, '<path d="M3 11a9 9 0 1 1 3 7M3 4v7h7"/>');
 addRotation('Girar 45° a la derecha', 45, '<path d="M21 11a9 9 0 1 0 -3 7M21 4v7h-7"/>');
